def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Vertex-degree-per-neighbour-colour entropy of the candidate's colour usage profile."""
    k = neighbor_colors.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    total = neighbor_colors.sum(axis=1, keepdims=True).astype(float)
    p = np.where(total > 0, neighbor_colors / np.maximum(total, 1.0), 0.0)
    ent = -np.sum(np.where(p > 0, p * np.log(p + 1e-12), 0.0), axis=1)
    norm = np.log(c + 1.0)
    return np.where(norm > 0, ent / norm, 0.0)
